CREATE OR REPLACE FUNCTION get_alerts (
  p_branch  IN VARCHAR2 DEFAULT NULL,
  p_min_amt IN NUMBER   DEFAULT NULL,
  p_from_dt IN DATE     DEFAULT NULL
) RETURN SYS_REFCURSOR
IS
  l_sql VARCHAR2(4000) :=
    'SELECT alert_id, cust_id, branch_code, alert_amt, alert_dt'
    || ' FROM aml_alert WHERE status = ''OPEN''';
  l_rc  SYS_REFCURSOR;
BEGIN
  IF p_branch IS NOT NULL THEN
    l_sql := l_sql || ' AND branch_code = :b';
  ELSE
    l_sql := l_sql || ' AND (1 = 1 OR :b IS NULL)';
  END IF;

  IF p_min_amt IS NOT NULL THEN
    l_sql := l_sql || ' AND alert_amt >= :a';
  ELSE
    l_sql := l_sql || ' AND (1 = 1 OR :a IS NULL)';
  END IF;

  IF p_from_dt IS NOT NULL THEN
    l_sql := l_sql || ' AND alert_dt >= :d';
  ELSE
    l_sql := l_sql || ' AND (1 = 1 OR :d IS NULL)';
  END IF;

  l_sql := l_sql || ' ORDER BY alert_amt DESC';

  OPEN l_rc FOR l_sql USING p_branch, p_min_amt, p_from_dt;
  RETURN l_rc;
END get_alerts;
/

DECLARE
  TYPE t_gl_map IS TABLE OF NUMBER INDEX BY VARCHAR2(10);
  l_gl  t_gl_map;
  l_key VARCHAR2(10);
BEGIN
  FOR g IN (SELECT gl_code, balance FROM gl_balance) LOOP
    l_gl(g.gl_code) := g.balance;
  END LOOP;

  FOR s IN (SELECT gl_code, sl_balance FROM subledger_total ORDER BY gl_code) LOOP
    IF NOT l_gl.EXISTS(s.gl_code) THEN
      INSERT INTO recon_break (gl_code, gl_bal, sl_bal, diff)
      VALUES (s.gl_code, NULL, s.sl_balance, -s.sl_balance);
    ELSE
      IF l_gl(s.gl_code) <> s.sl_balance THEN
        INSERT INTO recon_break (gl_code, gl_bal, sl_bal, diff)
        VALUES (s.gl_code, l_gl(s.gl_code), s.sl_balance,
                l_gl(s.gl_code) - s.sl_balance);
      END IF;
      l_gl.DELETE(s.gl_code);
    END IF;
  END LOOP;

  l_key := l_gl.FIRST;
  WHILE l_key IS NOT NULL LOOP
    INSERT INTO recon_break (gl_code, gl_bal, sl_bal, diff)
    VALUES (l_key, l_gl(l_key), NULL, l_gl(l_key));
    l_key := l_gl.NEXT(l_key);
  END LOOP;

  COMMIT;
END;
/

DECLARE
  l_bal acct_balance.balance%TYPE;
BEGIN
  FOR r IN (SELECT loan_no, acct_no, emi_amt
            FROM   emi_due
            ORDER  BY loan_no) LOOP
    SAVEPOINT before_emi;

    UPDATE acct_balance
    SET    balance = balance - r.emi_amt
    WHERE  acct_no = r.acct_no
    RETURNING balance INTO l_bal;

    INSERT INTO loan_receipt (loan_no, amount)
    VALUES (r.loan_no, r.emi_amt);

    IF l_bal < 0 THEN
      ROLLBACK TO before_emi;
      SELECT balance INTO l_bal
      FROM   acct_balance
      WHERE  acct_no = r.acct_no;
      INSERT INTO emi_run_log (loan_no, acct_no, status, bal_after)
      VALUES (r.loan_no, r.acct_no, 'BOUNCED', l_bal);
    ELSE
      INSERT INTO emi_run_log (loan_no, acct_no, status, bal_after)
      VALUES (r.loan_no, r.acct_no, 'PAID', l_bal);
    END IF;
  END LOOP;
  COMMIT;
END;
/

